<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap/cli.php';

use App\Database\Migration005VehicleValidator as V;
use App\Database\MigrationTarget;
use App\Database\SafetyException;

$n=0;$ok=static function(bool $v,string $m)use(&$n):void{if(!$v)throw new RuntimeException('FAIL '.$m);$n++;};
$reject=static function(callable $f):bool{try{$f();return false;}catch(SafetyException){return true;}};
$ok(V::assertTarget(MigrationTarget::TEST)===null,'test target accepted');
$ok($reject(fn()=>V::assertTarget(MigrationTarget::PRODUCTION)),'production target rejected');
$ok($reject(fn()=>V::assertLedgerApplied(['version'=>V::VERSION,'checksum'=>str_repeat('0',64),'status'=>'applied','completed_statements'=>1,'total_statements'=>1])),'checksum mismatch rejected');
$ok($reject(fn()=>V::assertLedgerApplied(['version'=>V::VERSION,'checksum'=>V::SHA256,'status'=>'applied','completed_statements'=>0,'total_statements'=>1])),'statement count mismatch rejected');
$ok($reject(fn()=>V::assertLedgerApplied(['version'=>'001_identity'])),'missing migration row rejected');
$ok($reject(fn()=>V::assertLedgerApplied(['version'=>V::VERSION,'checksum'=>V::SHA256,'status'=>'started','completed_statements'=>1,'total_statements'=>1])),'partial ledger rejected');
$plan=App\Database\MigrationPlan::load();
$baseline=array_map(static fn(array $e):array=>['version'=>$e['version'],'checksum'=>$e['sha256'],'status'=>'applied','completed_statements'=>count($e['statements']),'total_statements'=>count($e['statements'])],array_slice($plan,0,4));
$ok(V::baselineLedgerError($plan,$baseline)===null,'applied 001–004 with matching checksums/counts and absent 005 are pending-ready');
$bad=$baseline;$bad[1]['checksum']=str_repeat('0',64);
$ok(V::baselineLedgerError($plan,$bad)==='LEDGER_CHECKSUM_MISMATCH','baseline checksum mismatch is identified');
$ok(V::baselineLedgerError($plan,array_slice($baseline,0,3))==='LEDGER_ROWS_NOT_BASELINE','missing migration is identified');
$bad=$baseline;$bad[2]['status']='started';
$ok(V::baselineLedgerError($plan,$bad)==='LEDGER_PARTIAL_OR_UNAPPLIED','partial migration is identified');
$ok(V::safetyCode('Migration 005 schema drift detected.')==='VEHICLE_SCHEMA_DRIFT','CLI safety code is specific and safe');
$partialColumns=V::vehicleColumnDiff(['id','registration_number']);
$ok($partialColumns['missing']===array_slice(V::expectedVehicleColumns(),2) && $partialColumns['unexpected']===[],'column visibility diagnostic lists missing names without reading data rows');
$ok(V::safetyCode('Migration 005 vehicle column metadata is incomplete or differs from expected schema.')==='VEHICLE_METADATA_INCOMPLETE','incomplete visible metadata receives a distinct safe error code');
$indexes=[['uq_vehicle_registration','registration_number',1,0],['uq_vehicle_registration','registration_province',2,0]];
$oldColumns=['id','registration_number','registration_province','label','passenger_capacity','is_active','created_by','updated_by','created_at','updated_at'];
$ok(V::assertPreconditions($oldColumns,$indexes,[])===null,'expected old schema passes');
$ok($reject(fn()=>V::assertPreconditions(['registration_province','other'],$indexes,[])),'schema drift rejected');
$ok($reject(fn()=>V::assertPreconditions($oldColumns,$indexes,[['registration_number'=>'DUP']])),'duplicate registration rejected using grouped column collation');
$ok($reject(fn()=>V::assertPreconditions($oldColumns,[],[])),'missing old index rejected');
$ok(!is_file(sys_get_temp_dir().'/missing-upvan-backup-'.bin2hex(random_bytes(8)).'.sql'),'missing backup is detectable without reading contents');
$cli=file_get_contents(dirname(__DIR__,2).'/bin/db-migration-005-preflight.php');
$runner=file_get_contents(dirname(__DIR__,2).'/app/Database/MigrationRunner.php');
$ok(str_contains($cli,"'PDO_ERROR'") && str_contains($cli,"'sqlstate'") && str_contains($cli,"'native_code'"),'PDO failure is reported with safe codes');
$ok(str_contains($runner,'lastReadCheck()') && str_contains($runner,"'LEDGER_SELECT'"),'Runner identifies the exact ledger read check');
$ok(str_contains($cli,'$runner->lastReadCheck()'),'CLI forwards the safe failed-check name');
$ok(str_contains($cli,"migration_account") && str_contains($cli,"up_van_test_migrator@127.0.0.1"),'preflight uses the dedicated migration account, never auth runtime');
$ok(str_contains($cli,"ConnectionFactory::connect('migration_test')") && !str_contains($cli,'new \\PDO('),'live preflight exercises the same pinned scoped-grant guard as migration apply');
$ok(str_contains($cli,'filesize($backup)>0') && !str_contains($cli,'file_get_contents($backup)'),'backup check uses existence/size only');
$ok(str_contains($runner,'vehicle005Preflight()') && str_contains($runner,'GROUP BY registration_number HAVING COUNT(*)>1'),'Runner preflight checks duplicates and live ledger');
$grants=V::readOnlyPreflightGrants();
$ok(count($grants)===3 && str_contains($grants[0],'vehicles') && str_contains($grants[0],'registration_number') && str_contains($grants[0],'updated_at'),'vehicles read grant covers complete schema metadata');
$ok(str_contains($grants[1],'booking_requests') && str_contains($grants[2],'vehicle_assignments'),'related counts have table-specific grants');
$ok(!str_contains(implode(' ',$grants),'schema_migrations') && !str_contains(implode(' ',$grants),'up_van_auth_test'),'plan does not duplicate ledger or runtime grants');
$ok(str_contains($runner,"'DUPLICATE_REGISTRATION'") && str_contains($runner,"'REFERENCE_COUNTS'") && str_contains($runner,"'VEHICLE_INDEXES'"),'query failures use named checks');
foreach(['INSERT ','UPDATE ','DELETE ','ALTER ','CREATE ','DROP ','GRANT ','REVOKE '] as $forbidden)$ok(!str_contains(strtoupper($cli),$forbidden),'CLI source excludes '.$forbidden);
echo "PASS: $n Migration 005 preflight offline checks; no database connected.".PHP_EOL;
